/** The checked-in artifact is generated by the production Rust GPX exporter.
 * These tests always run: no optional fixture/kernel skip in frontend CI.
 */
import { readFileSync } from "node:fs";
import { tableFromIPC, tableToIPC, Uint64, vectorFromArray } from "apache-arrow";
import { describe, expect, it } from "vitest";
import { loadLedger } from "./loader";
import { taiCalendarToNs } from "../core/epoch";
import { buildTimelines, EntityTimeline } from "../core/timeline";
import { WorldResolver } from "../core/worldResolve";
import { rotateVec } from "../core/quat";
import { countAtOrBefore, guideLines } from "../scene/orbits";

const bytes = readFileSync(new URL("../../public/data/halifax-gpx.arrows", import.meta.url));
const names = readFileSync(new URL("../../public/data/halifax-gpx.arrows.names.arrow", import.meta.url));
const load = () => loadLedger(bytes, names);
const t0 = taiCalendarToNs(2025, 1, 1, 12, 0, 37); // Recorded 12:00:00 UTC.
const seconds = (s: number) => t0 + BigInt(s) * 1_000_000_000n;
const fixes = [
  [44.6488, -63.5752, 10],
  [44.6490, -63.5750, 11],
  [44.6492, -63.5748, 12],
  [44.6500, -63.5740, 13],
  [44.6502, -63.5738, 14],
] as const;

describe("production GPX → ledger IPC → Earth-relative playback", () => {
  it("loads the full normalized journey, registered names and exact source continuity", () => {
    const data = load();
    expect(data.rows).toHaveLength(14); // five observations + nine sampled frame poses
    expect(data.entities.size).toBe(2);
    expect(data.minEpochNs).toBe(t0);
    expect(data.maxEpochNs).toBe(seconds(310));
    const rows = data.rows.filter((r) => r.gpx);
    expect(rows).toHaveLength(5);
    expect(rows.every((r) => r.frameId === data.gpxPlayback!.earthFrameId)).toBe(true);
    expect(rows.map((r) => r.epochNs)).toEqual([0, 10, 20, 300, 310].map(seconds));
    expect(rows.map((r) => [r.gpx!.source, r.gpx!.object, r.gpx!.segment, r.gpx!.point]))
      .toEqual([1n, 2n, 3n, 1n, 2n].map((point, i) => ["halifax.gpx", "track:1", i < 3 ? 1n : 2n, point]));
    expect(data.names.label(rows[0]!.entityId)).toBe("halifax-vessel");
    expect(data.names.label(rows[0]!.sourceId)).toBe("synthetic-gpx");
    expect(rows.every((r) => r.unitsPos === "m" && r.timescaleId === "TAI" && r.estimateType === "SIMULATED")).toBe(true);
    expect(rows.every((r) => r.velocity === null && r.positionCovariance === null)).toBe(true);
  });

  it("preserves Halifax longitude, geodetic latitude, ellipsoidal height and metre scale", () => {
    const rows = load().rows.filter((r) => r.gpx);
    const a = 6_378_137;
    const e2 = 1 - (1 - 1 / 298.257223563) ** 2;
    rows.forEach((row, i) => {
      const [lat, lon, h] = fixes[i]!;
      const phi = lat * Math.PI / 180;
      const lambda = lon * Math.PI / 180;
      const n = a / Math.sqrt(1 - e2 * Math.sin(phi) ** 2);
      const surface = [n * Math.cos(phi) * Math.cos(lambda), n * Math.cos(phi) * Math.sin(lambda), n * (1 - e2) * Math.sin(phi)];
      const normal = [Math.cos(phi) * Math.cos(lambda), Math.cos(phi) * Math.sin(lambda), Math.sin(phi)];
      for (let k = 0; k < 3; k++) expect(row.position[k]).toBeCloseTo(surface[k]! + h * normal[k]!, 7);
      const height = row.position.reduce((sum, p, k) => sum + (p - surface[k]!) * normal[k]!, 0);
      expect(height).toBeCloseTo(h, 7);
      expect(Math.atan2(row.position[1], row.position[0]) * 180 / Math.PI).toBeCloseTo(lon, 10);
      expect(row.position[0]).toBeGreaterThan(0);
      expect(row.position[1]).toBeLessThan(0); // west of Greenwich
      expect(row.position[2]).toBeGreaterThan(0); // northern hemisphere
      expect(Math.hypot(...row.position)).toBeGreaterThan(6_360_000);
    });
  });

  it("resolves samples through a rotating ITRF93 frame, with no fabricated Earth translation", () => {
    const data = load();
    const timelines = buildTimelines(data.entities);
    const world = new WorldResolver(timelines);
    const earth = data.gpxPlayback!.earthFrameId;
    const anchors = data.entities.get(earth)!;
    const observations = data.rows.filter((r) => r.gpx);
    expect(anchors.every((r) => r.position.every((p) => p === 0) && !r.gpx)).toBe(true);
    for (const row of observations) {
      expect(anchors.some((anchor) => anchor.epochNs === row.epochNs)).toBe(true);
      const pose = world.worldPoseAt(row.entityId, row.epochNs);
      const expected = rotateVec(world.worldPoseAt(earth, row.epochNs).q, row.position.map((p) => p / 1000) as [number, number, number]);
      expected.forEach((p, i) => expect(pose.p[i]).toBeCloseTo(p, 9));
      expect(Math.hypot(...pose.p)).toBeCloseTo(Math.hypot(...row.position) / 1000, 9);
    }
    const x0 = rotateVec(world.worldPoseAt(earth, t0).q, [1, 0, 0]);
    const x1 = rotateVec(world.worldPoseAt(earth, seconds(310)).q, [1, 0, 0]);
    const north = rotateVec(world.worldPoseAt(earth, t0).q, [0, 0, 1]);
    const cross = [x0[1] * x1[2] - x0[2] * x1[1], x0[2] * x1[0] - x0[0] * x1[2], x0[0] * x1[1] - x0[1] * x1[0]];
    const angle = Math.atan2(cross.reduce((s, c, i) => s + c * north[i]!, 0), x0.reduce((s, c, i) => s + c * x1[i]!, 0));
    expect(angle).toBeGreaterThan(0.0225); // eastward ~1.295 degrees over 310 seconds
    expect(angle).toBeLessThan(0.0227);
  });

  it("interpolates only inside each segment, and never invents a world pose in the gap", () => {
    const data = load();
    const rows = data.rows.filter((r) => r.gpx);
    const timeline = new EntityTimeline(rows);
    for (const time of [0, 5, 10, 20, 300, 305, 310]) expect(timeline.sampleAt(seconds(time))).not.toBeNull();
    for (const time of [-1, 21, 150, 299, 311]) expect(timeline.sampleAt(seconds(time))).toBeNull();
    const midpoint = timeline.sampleAt(seconds(5))!;
    rows[0]!.position.forEach((p, k) => expect(midpoint.positionKm[k]).toBeCloseTo((p + rows[1]!.position[k]!) / 2000, 10));
    const world = new WorldResolver(buildTimelines(data.entities));
    expect(() => world.worldPoseAt(rows[0]!.entityId, seconds(150))).toThrow(/observation|available/i);
    const guides = guideLines(rows, data.gpxPlayback!.earthFrameId);
    expect(guides.map((g) => g.kind)).toEqual(["trail", "trail"]);
    expect(guides.map((g) => g.epochs!.length)).toEqual([3, 2]);
    expect(countAtOrBefore(guides[1]!.epochs!, seconds(299))).toBe(0);
    expect(countAtOrBefore(guides[1]!.epochs!, seconds(310))).toBe(2);
  });

  it("does not depend on the cosmetic name sidecar for geometry or gap handling", () => {
    const data = loadLedger(bytes);
    expect(data.gpxPlayback!.earthFrameId).toBe(load().gpxPlayback!.earthFrameId);
    const rows = data.rows.filter((r) => r.gpx);
    expect(new EntityTimeline(rows).sampleAt(seconds(100))).toBeNull();
  });
});

describe("incomplete or incompatible playback artifacts fail explicitly", () => {
  it("rejects unknown versions and missing profile metadata", () => {
    for (const version of ["2", undefined]) {
      const table = tableFromIPC(bytes);
      if (version) table.schema.metadata.set("soloc:gpx_playback", version);
      else table.schema.metadata.delete("soloc:gpx_playback");
      expect(() => loadLedger(tableToIPC(table, "file"))).toThrow(/GPX|playback/i);
    }
  });

  it("rejects missing provenance columns or a partly null track provenance", () => {
    const table = tableFromIPC(bytes);
    expect(() => loadLedger(tableToIPC(table.select(table.schema.fields.map((f) => f.name).filter((n) => n !== "gpx_point")), "file"))).toThrow(/GPX|provenance/i);
    const broken = table.setChild("gpx_segment", vectorFromArray(
      [null, 1n, 1n, 2n, 2n, ...Array<null>(9).fill(null)], new Uint64(),
    ));
    expect(() => loadLedger(tableToIPC(broken, "file"))).toThrow(/provenance/i);
  });

  it("rejects absent, truncated, duplicate or excessively sparse frame timelines", () => {
    const table = tableFromIPC(bytes);
    const cases = [
      table.slice(0, 5),
      table.slice(0, 13),
      table.concat(table.slice(5, 6)),
      table.slice(0, 6).concat(table.slice(13, 14)),
    ];
    for (const invalid of cases) expect(() => loadLedger(tableToIPC(invalid, "file"))).toThrow(/ITRF93|anchor|cover|300 seconds/i);
  });
});
